bool solve(int row, int n, vector<int>& colForRow,
           unordered_set<int>& usedCols,
           unordered_set<int>& usedDiag1, // row + col
           unordered_set<int>& usedDiag2, // row - col
           vector<vector<int>>& solutions) {
    if (row == n) {
        solutions.push_back(colForRow); // record a copy
        return true; // remove this line if you want ALL solutions, not just the first
    }
    bool foundAny = false;
    for (int col = 0; col < n; col++) {
        int d1 = row + col, d2 = row - col;
        if (usedCols.count(col) || usedDiag1.count(d1) || usedDiag2.count(d2)) continue;

        // choose
        colForRow[row] = col;
        usedCols.insert(col); usedDiag1.insert(d1); usedDiag2.insert(d2);

        // explore
        if (solve(row + 1, n, colForRow, usedCols, usedDiag1, usedDiag2, solutions)) {
            foundAny = true;
        }

        // unchoose
        usedCols.erase(col); usedDiag1.erase(d1); usedDiag2.erase(d2);
    }
    return foundAny;
}

vector<vector<int>> solveNQueens(int n) {
    vector<vector<int>> solutions;
    vector<int> colForRow(n, -1);
    unordered_set<int> usedCols, usedDiag1, usedDiag2;
    solve(0, n, colForRow, usedCols, usedDiag1, usedDiag2, solutions);
    return solutions;
}
